def transform(grid):
    h,w=len(grid),len(grid[0])
    # separators are full 8-lines; tile dimensions are 3x3
    rs=[i for i,row in enumerate(grid) if all(v==8 for v in row)]
    cs=[j for j in range(w) if all(row[j]==8 for row in grid)]
    rstarts=[0]+[x+1 for x in rs]
    cstarts=[0]+[x+1 for x in cs]
    rh=(rs[0] if rs else h)
    cw=(cs[0] if cs else w)
    cells={}
    for tr,r in enumerate(rstarts):
      for tc,c in enumerate(cstarts):
        vals=[grid[i][j] for i in range(r,min(r+rh,h)) for j in range(c,min(c+cw,w)) if grid[i][j] not in (0,8)]
        if vals: cells[(tr,tc)]=vals[0]
    colors=sorted(set(cells.values()))
    painted={}
    for color in colors:
      pts=[p for p,v in cells.items() if v==color]
      if len(pts)>=2:
        # aligned seeds paint the inclusive intervening row/column
        for a in pts:
          for b in pts:
            if a[0]==b[0]:
              for c in range(min(a[1],b[1]),max(a[1],b[1])+1): painted[(a[0],c)]=painted.get((a[0],c),set())|{color}
            if a[1]==b[1]:
              for r in range(min(a[0],b[0]),max(a[0],b[0])+1): painted[(r,a[1])]=painted.get((r,a[1]),set())|{color}
    out=[row[:] for row in grid]
    for (tr,tc),cols in painted.items():
      color=next(iter(cols)) if len(cols)==1 else 6
      r,c=rstarts[tr],cstarts[tc]
      for i in range(r,min(r+rh,h)):
       for j in range(c,min(c+cw,w)): out[i][j]=color
    return out
